			'.aurora-set-seg-item{appearance:none;height:26px;padding:0 12px;border:0;border-radius:8px;background:transparent;color:#7C6453;font-size:12px;cursor:pointer;transition:background .2s ease,color .2s ease}',
			'.aurora-set-seg-item:hover:not(:disabled){color:#33241B}',
			'.aurora-set-seg-item.is-on{background:hsla(var(--aurora-hue,18),100%,99%,.98);color:#33241B;font-weight:600;box-shadow:0 1px 4px rgba(120,74,46,.16)}',
			'.aurora-set-seg-item:disabled{cursor:not-allowed;opacity:.55}',
			'.aurora-set-seg-item:focus-visible{outline:2px solid hsl(var(--aurora-hue,18),78%,42%);outline-offset:1px}',
			/* ---- 色轮 ---- */
			'.aurora-set-wheel-card{display:flex;flex-direction:row;align-items:center;justify-content:center;gap:30px;flex-wrap:wrap;padding:22px 18px}',
			'.aurora-set-wheelwrap{position:relative;width:188px;height:188px;flex:none}',
			'.aurora-set-wheel{position:absolute;inset:0;border-radius:50%;cursor:crosshair;background:conic-gradient(from 0deg,hsl(0,85%,56%),hsl(45,85%,56%),hsl(90,85%,56%),hsl(135,85%,56%),hsl(180,85%,56%),hsl(225,85%,56%),hsl(270,85%,56%),hsl(315,85%,56%),hsl(360,85%,56%));-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 24px),#000 calc(100% - 23px));mask:radial-gradient(farthest-side,transparent calc(100% - 24px),#000 calc(100% - 23px))}',
			'.aurora-set-wheel:focus-visible{outline:2px solid hsl(var(--aurora-hue,18),78%,42%);outline-offset:5px;border-radius:50%}',
			'.aurora-set-wheelhub{position:absolute;inset:32px;border-radius:50%;display:grid;place-items:center;background:hsla(var(--aurora-hue,18),100%,98%,.94);border:1px solid rgba(120,74,46,.16);font-family:var(--as-mono);font-size:12.5px;font-weight:600;color:#5A4436;box-shadow:inset 0 1px 0 rgba(255,255,255,.8)}',
