			'.aurora-set-num:focus{border-color:hsl(var(--aurora-hue,18),78%,42%);box-shadow:0 0 0 3px hsla(var(--aurora-hue,18),78%,42%,.16)}',
			'.aurora-set-num:disabled{opacity:.55;cursor:not-allowed}',
			/* ---- 灵感色板 ---- */
			'.aurora-set-swatches{display:flex;flex-wrap:wrap;gap:9px}',
			'.aurora-set-swatch{appearance:none;width:26px;height:26px;border-radius:50%;border:0;padding:0;cursor:pointer;box-shadow:inset 0 0 0 1px rgba(120,74,46,.16);transition:transform .2s cubic-bezier(.34,1.56,.64,1),box-shadow .2s ease}',
			'.aurora-set-swatch:hover{transform:scale(1.16)}',
			'.aurora-set-swatch.is-on{box-shadow:0 0 0 2px #FFF9F4,0 0 0 4px hsl(var(--aurora-hue,18),78%,42%)}',
			'.aurora-set-swatch:focus-visible{outline:2px solid #33241B;outline-offset:3px}',
			/* ---- 界面网格 ---- */
			'.aurora-set-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(250px,100%),1fr));gap:13px}',
			'.aurora-part{display:flex;flex-direction:column;padding:14px 16px;border-radius:14px;background:hsla(var(--aurora-hue,18),100%,96%,.92);border:1px solid rgba(120,74,46,.16);box-shadow:0 2px 14px rgba(120,74,46,.07),inset 0 1px 0 rgba(255,255,255,.55);transition:transform .22s ease,box-shadow .22s ease}',
			'.aurora-part:hover{transform:translateY(-2px);box-shadow:0 11px 26px -15px rgba(120,74,46,.55)}',
			'.aurora-part.is-off{opacity:.78}',
			'.aurora-part-head{display:flex;align-items:flex-start;gap:10px;margin-bottom:11px}',
			'.aurora-part-ico{width:30px;height:30px;flex:none;border-radius:9px;display:grid;place-items:center;color:hsl(var(--aurora-hue,18),78%,42%);background:hsla(var(--aurora-hue,18),100%,91%,.95)}',
			'.aurora-part-titles{display:flex;flex-direction:column;min-width:0}',
			'.aurora-part-name{font-size:13px;font-weight:600;line-height:1.3}',
