			'.aurora-part-badge{margin-left:auto;align-self:center;font-family:var(--as-mono);font-size:10.5px;color:#7C6453;background:rgba(120,74,46,.08);border-radius:99px;padding:2px 8px;white-space:nowrap}',
			'.aurora-part-row{display:grid;grid-template-columns:46px 1fr 42px;align-items:center;gap:9px;padding:4px 0}',
