			'.aurora-part-val{font-family:var(--as-mono);font-variant-numeric:tabular-nums;text-align:right;font-size:11px;color:#7C6453}',
			/* ---- 占位页 ---- */
			'.aurora-set-empty{display:flex;flex-direction:column;align-items:center;gap:9px;padding:40px 22px;text-align:center;border-radius:16px;border:1px dashed rgba(120,74,46,.30);background:hsla(var(--aurora-hue,18),100%,98%,.55)}',
			'.aurora-set-empty-ico{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;color:hsl(var(--aurora-hue,18),78%,42%);background:hsla(var(--aurora-hue,18),100%,92%,.9);margin-bottom:2px}',
			'.aurora-set-empty-ico svg{width:20px;height:20px}',
